41	      b.challenger_id === player.id ? b.opponent_id : b.challenger_id;
42	
43	    const [opponentResult, roundsResult] = await Promise.all([
44	      opponentId
45	        ? supabase.from("players").select("name").eq("id", opponentId).single()
46	        : Promise.resolve({ data: null }),
47	      supabase.from("rounds").select("*").eq("battle_id", id),
48	    ]);
49	
50	    if (opponentResult.data) setOpponentName(opponentResult.data.name);
51	    const rounds = roundsResult.data;
52	
53	    const myR = rounds?.find((r: Round) => r.player_id === player.id) ?? null;
