88	        "postgres_changes",
89	        {
90	          event: "*",
91	          schema: "public",
92	          table: "rounds",
93	          filter: `battle_id=eq.${id}`,
94	        },
95	        () => loadBattle()
96	      )
97	      .subscribe();
98	
99	    return () => {
100	      supabase.removeChannel(channel);
101	    };
102	  }, [battle, phase, id, loadBattle]);
103	
104	  function startSolving() {
105	    setStartedAt(new Date());
106	    setPhase("solving");
107	  }
108	
109	  const handleElapsed = useCallback((ms: number) => {
110	    setElapsedMs(ms);
111	  }, []);
