116	    setCalculations(updated);
117	
118	    if (currentIndex + 1 < calculations.length) {
119	      setCurrentIndex(currentIndex + 1);
120	    } else {
121	      const finishedAt = new Date();
122	      const ms = finishedAt.getTime() - startedAt!.getTime();
123	      setElapsedMs(ms);
124	
125	      const correctCount = updated.filter(
126	        (c) => c.playerAnswer === c.answer
127	      ).length;
128	
129	      await supabase.from("rounds").insert({
130	        player_id: player!.id,
131	        stufe: battle!.stufe,
132	        started_at: startedAt!.toISOString(),
133	        finished_at: finishedAt.toISOString(),
134	        correct_count: correctCount,
135	        calculations: updated,
136	        battle_id: id,
137	      });
138	
139	      await loadBattle();
140	    }
141	  }
142	
143	  if (!player) {
144	    return (
145	      <div className="text-center pt-12">
146	        <p className="text-xl mb-4">Bitte melde dich zuerst an!</p>
147	        <Link href="/" className="text-blue-500 underline text-xl">
148	          Zur Startseite
149	        </Link>
150	      </div>
151	    );
152	  }
153	
154	  if (phase === "loading") {
155	    return <div className="text-center pt-12 text-xl">Laden...</div>;
156	  }
157	
158	  if (phase === "ready") {
159	    return (
160	      <div className="flex flex-col items-center gap-6 pt-12">
161	        <h1 className="text-3xl font-bold">Duell</h1>
162	        {opponentName && (
163	          <p className="text-xl">
164	            Gegen <span className="font-bold">{opponentName}</span>
165	          </p>
166	        )}
167	        {battle && (
